using InternalsViewer.Connection.BackupFile.Reader;
using InternalsViewer.Connection.BackupFile.Format.Blocks.Descriptors.SqlServer;
using InternalsViewer.Connection.BackupFile.Format.Streams;
using Microsoft.Extensions.Logging;
using Xunit.Abstractions;

namespace InternalsViewer.Connection.BackupFile.Tests;

public class BackupLoaderTests(ITestOutputHelper testOutput)
{
    public ITestOutputHelper TestOutput { get; } = testOutput;

    /// <summary>
    /// 
    /// </summary>
    /// <remarks>
    /// To generate backup files:
    ///     
    ///     BACKUP DATABASE TestDatabase
    ///     To DISK='C:\Temp\TestBackups\TestDatabase_Full.bak'
    ///     WITH FORMAT,
    ///     MEDIANAME = 'TEST_DATABASE_FULL',
    ///     NAME = 'Full Test Database Backup';
    ///     
    ///     BACKUP DATABASE TestDatabase TO 
    ///     DISK = 'C:\Temp\TestBackups\TestDatabase_Full_MultiFile_1.bak', 
    ///     DISK = 'C:\Temp\TestBackups\TestDatabase_Full_MultiFile_2.bak', 
    ///     DISK = 'C:\Temp\TestBackups\TestDatabase_Full_MultiFile_3.bak', 
    ///     DISK = 'C:\Temp\TestBackups\TestDatabase_Full_MultiFile_4.bak' 
    ///     WITH INIT, NAME = 'Full Test Database Backup (Multi)', STATS = 5
    ///     
    ///     BACKUP DATABASE TestDatabase
    ///     To DISK='C:\Temp\TestBackups\TestDatabase_Diff.bak'
    ///     WITH DIFFERENTIAL,
    ///     MEDIANAME = 'TEST_DATABASE_DIFF',
    ///     NAME = 'Differential Test Database Backup';
    ///     
    ///     BACKUP LOG TestDatabase
    ///     To DISK='C:\Temp\TestBackups\TestDatabase_TailLog.trn'
    ///     WITH CONTINUE_AFTER_ERROR;
    ///
    ///     BACKUP DATABASE TestDatabase TO 
    ///     DISK = 'C:\Temp\TestBackups\TestDatabase_Compressed_MS_XPRESS.bak'
    ///     WITH COMPRESSION (ALGORITHM = MS_XPRESS);
    /// 
    /// </remarks>
    [Theory]
    [InlineData(@"C:\Temp\TestBackups\TestDatabase_Full.bak")]
    [InlineData(@"C:\Temp\TestBackups\TestDatabase_Full_MultiFile_1.bak")]
    [InlineData(@"C:\Temp\TestBackups\TestDatabase_Diff.bak")]
    public void Can_Load(string filename)
    {
        TestOutput.WriteLine(filename);

        var loader = new BackupFileLoader(TestLogger.GetLogger<BackupFileLoader>(TestOutput), filename);

        var blocks = loader.Load();

        TestOutput.WriteLine($"Summary: {filename}");
        TestOutput.WriteLine(string.Empty);

        foreach (var block in blocks)
        {
            TestOutput.WriteLine($"{block.StartPosition:00000000}: {block.BlockType}");
        }

        TestOutput.WriteLine(string.Empty);
        TestOutput.WriteLine($"Details:");
        TestOutput.WriteLine(string.Empty);

        foreach (var block in blocks)
        {
            foreach (var s in block.Streams)
            {
                TestOutput.WriteLine($"{s.Header}");

                TestOutput.WriteLine(block.BlockType.ToString());
                if (s.Header.StreamId != StreamTypes.EndPadStream
                    && s.Header.StreamId != StreamTypes.StartPadStream
                    && s.Header.StreamLength <= 8192)
                {
                    var data = s.Data;

                    var utfValue = System.Text.Encoding.UTF8.GetString(s.Data, 0, s.Data.Length);

                    var unicodeValue = System.Text.Encoding.Unicode.GetString(s.Data, 0, s.Data.Length);

                    TestOutput.WriteLine($"**Stream Data: ({s.Header.StreamId})");
                    TestOutput.WriteLine(StringHelpers.ToHexString(data));
                    TestOutput.WriteLine("UTF: " + utfValue);
                    TestOutput.WriteLine("Unicode: " + unicodeValue);

                }
            }
        }
    }
}

public class BlockTests
{
    [Fact]
    public void Can_Read_SCIN_Block()
    {
        var dataString = "";

        var data = dataString.ToByteArray();

        var reader = new BackupReader(data);

        var block = new StreamBlock(reader);
    }
}